  Lemma Z_rec_other_sh : forall x lo' kk a, In x (chunk_list st) -> x <> ch -> ch_lo x <= lo' -> lo' + 8 * kk <= ch_end x -> lo' mod 8 = 0 -> 0 <= kk ->
